<script lang="ts">
  import {examplesPerSecond,quantizeScalar,tensorStorageMB} from '../../lib/curriculum';
  type Stability = 'healthy' | 'exploding' | 'stalled';
  let stability:Stability='healthy',batch=64,stepMs=80,value=.63,quantStep=.25,qat=false,quantized=0,error=0;
  const curves:Record<Stability,number[]>={healthy:[1.15,.92,.76,.64,.54,.47,.41,.36,.32,.29,.27],exploding:[1.05,.88,.79,.95,.72,1.18,.84,1.55,1.12,1.9,2.35],stalled:[1.08,1.03,1.01,1,.99,.99,.98,.98,.98,.98,.98]};
  const diagnoses:Record<Stability,string>={healthy:'Finite gradients, a downward trend, and no widening train/validation gap.',exploding:'Spikes or non-finite values: inspect the learning rate, inputs, normalization, and gradient norm.',stalled:'Little movement: check data and labels, frozen parameters, gradient scale, and learning rate.'};
  const x=(i:number)=>36+i*45,y=(v:number)=>178-Math.min(v,2.5)/2.5*140;
  $: path=curves[stability].map((v,i)=>`${i?'L':'M'} ${x(i)} ${y(v)}`).join(' ');
  const elements=64*128*768,fp32=tensorStorageMB(elements,32),fp16=tensorStorageMB(elements,16);
  $: throughput=examplesPerSecond(+batch,+stepMs);
  $: ({quantized,error}=quantizeScalar(+value,+quantStep));
</script>
<section class="lab" aria-labelledby="constraints-title">
  <header><div><span>Systems lab</span><h3 id="constraints-title">Three budgets govern a training run</h3></div><p>numerical range · bytes · time</p></header>
  <article class="panel stability"><div class="copy"><small>1 · numerical health</small><h4>Would you trust this loss curve?</h4><div class="switch">{#each ['healthy','exploding','stalled'] as item}<button class:active={stability===item} onclick={()=>stability=item as Stability}>{item}</button>{/each}</div><p>{diagnoses[stability]}</p></div><svg viewBox="0 0 520 210" role="img" aria-label={`${stability} loss curve`}><line x1="36" y1="178" x2="492" y2="178"/><line x1="36" y1="25" x2="36" y2="178"/><path d={path}/><text x="40" y="20">loss</text><text x="447" y="200">steps</text></svg></article>
  <article class="panel memory"><div class="copy"><small>2 · memory and throughput</small><h4>Which number is actually limiting the run?</h4><p>For one saved activation tensor with shape <code>[64, 128, 768]</code>, eligible values take exactly half the storage at 16 bits. Standard automatic mixed precision usually keeps FP32 model parameters and optimizer state; it does not halve every byte in the run.</p></div><div class="budget"><div class="memory-bars"><div>FP32 <b>{fp32.toFixed(1)} MB</b><i style="--width:100%"></i></div><div>FP16/BF16 <b>{fp16.toFixed(1)} MB</b><i style="--width:50%"></i></div></div><div class="throughput"><label>batch <b>{batch}</b><input type="range" min="16" max="256" step="16" bind:value={batch}/></label><label>step time <b>{stepMs} ms</b><input type="range" min="20" max="240" step="10" bind:value={stepMs}/></label><strong>{throughput.toFixed(0)} examples / second</strong><small>Throughput = batch size ÷ step time. Measure it; precision alone cannot predict it.</small></div></div></article>
  <article class="panel quantization"><div class="copy"><small>3 · representational error</small><h4>When does rounding become part of learning?</h4><p>Post-training quantization changes inference after training. Quantization-aware training inserts simulated rounding in the forward pass so the model can adapt before export.</p><button class:active={qat} onclick={()=>qat=!qat}>{qat?'QAT: simulated during training':'PTQ: applied after training'}</button></div><div class="number-line"><div class="values"><span>original <b>{(+value).toFixed(2)}</b></span><span>stored level <b>{quantized.toFixed(2)}</b></span><span>error <b>{error>=0?'+':''}{error.toFixed(2)}</b></span></div><div class="track"><i class="original" style={`left:${(+value)*100}%`}></i><i class="rounded" style={`left:${quantized*100}%`}></i></div><label>value <input type="range" min="0" max="1" step=".01" bind:value={value}/></label><label>quantization step <b>{(+quantStep).toFixed(2)}</b><input type="range" min=".05" max=".5" step=".05" bind:value={quantStep}/></label><footer>{qat?'Forward: fake quantization exposes rounding error. Backward: a surrogate gradient keeps learning possible.':'Training remains full precision; rounding error appears only in the exported inference model.'}</footer></div></article>
</section>
