ns:repeat(3,1fr);gap:.5rem}.values span{padding:.55rem;border:1px solid #344054;color:#9aa6b6;font-size:.58rem}.values b{display:block;color:white;font:.75rem var(--font-mono)}.track{position:relative;height:4px;margin:2.2rem .6rem;background:#526076}.track i{position:absolute;top:50%;width:14px;height:14px;transform:translate(-50%,-50%);border-radius:50%}.track .original{background:#8ea6ca}.track .rounded{border:3px solid #df7656}.number-line label{display:grid;grid-template-columns:1fr auto;color:#aab4c3;font-size:.61rem}.number-line input{grid-column:1/-1;accent-color:#df7656}.number-line footer{margin-top:.8rem;padding:.6rem;background:#1d2735;color:#aab4c3;font-size:.61rem}@media(max-width:700px){header{align-items:flex-start;gap:.5rem;flex-direction:column}.panel{grid-template-columns:1fr}.stability svg{min-height:210px}.throughput{grid-template-columns:1fr}.values{grid-template-columns:1fr 1fr}.values span:last-child{grid-column:1/-1}}
</style>
